/* Preview runtime. Reads design-data.json (generated by scripts/design-report.mts) so every value
 * on this page comes from the same source the tests check. No framework, no build step. */

const SERIF_NAMES = {
  'source-serif': 'Source Serif 4',
  newsreader: 'Newsreader',
  instrument: 'Instrument Serif',
};

const SWATCHES = [
  ['bg', 'page'],
  ['s1', 'panel'],
  ['s2', 'elevated'],
  ['line', 'hairline'],
  ['line-strong', 'control border'],
  ['fg', 'text'],
  ['fg-dim', 'text dim'],
  ['fg-faint', 'text faint'],
  ['accent', 'accent fill'],
  ['accent-ink', 'accent ink'],
  ['btn', 'primary button'],
  ['co-think', 'Co-think'],
  ['co-work', 'Co-work'],
  ['attn', 'attention'],
  ['danger', 'danger'],
  ['diff-add', 'diff add'],
  ['diff-del', 'diff del'],
];

const INSPECTOR_TOKENS = ['bg', 's1', 's2', 'line', 'line-strong', 'fg', 'fg-dim', 'fg-faint', 'accent', 'accent-ink', 'attn', 'danger'];

const state = {
  theme: 'anvil',
  mode: 'dark',
  serif: 'source-serif',
  contrast: false,
};

const $ = (selector) => {
  const node = document.querySelector(selector);
  if (!node) throw new Error(`preview markup is missing ${selector}`);
  return node;
};

const el = (tag, className, text) => {
  const node = document.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
};

const store = {
  read() {
    try {
      const raw = localStorage.getItem('selfimpulse.preview');
      if (!raw) return;
      const parsed = JSON.parse(raw);
      for (const key of Object.keys(state)) {
        if (parsed[key] !== undefined && typeof parsed[key] === typeof state[key]) state[key] = parsed[key];
      }
    } catch {
      /* a blocked storage API must not break the preview */
    }
  },
  write() {
    try {
      localStorage.setItem('selfimpulse.preview', JSON.stringify(state));
    } catch {
      /* ignore */
    }
  },
};

const data = await fetch('./design-data.json').then((response) => {
  if (!response.ok) throw new Error(`design-data.json ${response.status}`);
  return response.json();
});

const variantFor = (theme, mode) =>
  data.variants.find((v) => v.theme === theme && v.mode === mode) ?? data.variants[0];

const current = () => variantFor(state.theme, state.mode);

function apply() {
  const root = document.documentElement;
  root.dataset.theme = state.theme;
  root.dataset.mode = state.mode;
  root.dataset.serif = state.serif;
  if (state.contrast) root.dataset.contrast = 'high';
  else delete root.dataset.contrast;
  store.write();
  render();
}

function ratioFor(token, on) {
  const floor = current().floors.find((f) => f.token === token && f.on === on);
  return floor ? floor.ratio : null;
}

function renderThemes() {
  const host = $('#themes');
  host.replaceChildren();
  for (const theme of data.themes) {
    const dark = variantFor(theme.id, 'dark');
    const light = variantFor(theme.id, 'light');
    const button = el('button', 'theme-btn');
    button.type = 'button';
    button.setAttribute('aria-pressed', String(theme.id === state.theme));
    const text = el('span');
    text.append(el('span', 'theme-name', theme.label), el('span', 'theme-blurb', theme.blurb));
    const dots = el('span', 'mode-dots');
    for (const variant of [dark, light]) {
      const dot = el('span', 'swatch-dot');
      dot.style.background = variant.tokens.accent;
      dot.style.borderColor = variant.tokens['line-strong'];
      dots.append(dot);
    }
    button.append(text, dots);
    button.addEventListener('click', () => {
      state.theme = theme.id;
      apply();
    });
    host.append(button);
  }
}

function renderModes() {
  const host = $('#modes');
  host.replaceChildren();
  for (const mode of ['dark', 'light']) {
    const button = el('button', '', mode);
    button.type = 'button';
    button.setAttribute('aria-pressed', String(mode === state.mode));
    button.addEventListener('click', () => {
      state.mode = mode;
      apply();
    });
    host.append(button);
  }
}

function renderSerifs() {
  const host = $('#serifs');
  host.replaceChildren();
  for (const serif of data.serifs) {
    const card = el('button', 'serif-card');
    card.type = 'button';
    card.setAttribute('aria-pressed', String(serif === state.serif));
    const sample = el('span', 'serif-sample', 'A rehearsed change, then a real one.');
    sample.dataset.face = serif;
    const name = el('span', 'serif-name');
    name.append(el('span', '', SERIF_NAMES[serif] ?? serif), el('span', '', 'OFL'));
    card.append(sample, name);
    card.addEventListener('click', () => {
      state.serif = serif;
      apply();
    });
    host.append(card);
  }
}

function renderSwatches() {
  const host = $('#swatches');
  host.replaceChildren();
  const tokens = current().tokens;
  for (const [token, role] of SWATCHES) {
    const value = tokens[token];
    if (!value) continue;
    const box = el('div', 'swatch');
    const fill = el('div', 'swatch-fill');
    fill.style.background = `var(--${token})`;
    const meta = el('div', 'swatch-meta');
    const roleEl = el('div', 'swatch-role', role);
    const ratio = ratioFor(token, 'bg');
    if (ratio !== null) {
      const badge = el('span', 'swatch-ratio', `${ratio.toFixed(2)}`);
      badge.dataset.pass = String(ratio >= 3);
      roleEl.append(badge);
    }
    meta.append(roleEl, el('div', 'swatch-hex', value));
    box.append(fill, meta);
    host.append(box);
  }
}

function renderFloors() {
  const body = $('#floors');
  body.replaceChildren();
  for (const floor of current().floors) {
    const row = el('tr');
    row.append(
      el('td', 'id', `--${floor.token}`),
      el('td', '', floor.on),
      el('td', '', floor.ratio.toFixed(2)),
      el('td', '', String(floor.min)),
      el('td', '', floor.why),
    );
    body.append(row);
  }
  const summary = $('#floor-summary');
  summary.replaceChildren();
  const passed = current().floors.filter((f) => f.pass).length;
  for (const [key, value] of [
    ['checks', String(current().floors.length)],
    ['passing', String(passed)],
    ['failing', String(current().floors.length - passed)],
    ['floor', 'wcag 2.2'],
  ]) {
    summary.append(el('dt', '', key), el('dd', '', value));
  }
}

function renderTokens() {
  const host = $('#token-list');
  host.replaceChildren();
  const tokens = current().tokens;
  for (const token of INSPECTOR_TOKENS) {
    host.append(el('dt', '', `--${token}`), el('dd', '', tokens[token] ?? ''));
  }
  $('#serif-name').textContent = SERIF_NAMES[state.serif] ?? state.serif;
  $('#reduced').textContent = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'yes' : 'no';
  $('#variant-chip').textContent = `${state.theme} / ${state.mode}${state.contrast ? ' / high contrast' : ''}`;
  $('#cr-title').textContent = current().label;
  $('#cr-mode').textContent = state.mode;
}

function renderFonts() {
  const host = $('#font-list');
  host.replaceChildren();
  const seen = new Set();
  for (const font of data.fonts) {
    if (seen.has(font.out)) continue;
    seen.add(font.out);
    host.append(el('dt', '', font.out.replace('.woff2', '')), el('dd', '', `${font.pkg.split('/').pop()} ${font.version}`));
  }
}

function renderStates() {
  const host = $('#states');
  host.replaceChildren();
  for (const item of data.states) {
    const row = el('div', `state-row ${item.className}`);
    const glyph = el('span', `glyph tone-${item.tone}`);
    glyph.innerHTML = item.glyph;
    const text = el('span');
    text.append(el('span', 'state-label', item.label), el('span', 'state-reason', ` — ${item.reason}`));
    const meta = el('span', 't-meta', `${item.terminal ? 'terminal' : 'open'} · aria-live ${item.live}`);
    row.append(glyph, text, meta);
    host.append(row);
  }

  const children = $('#children');
  children.replaceChildren();
  const picks = [
    ['completed', 'reader · 8 pages · grant: web.read'],
    ['running', 'verifier · 4 checks · budget 12k'],
    ['needs-approval', 'writer · grant: file.write, attenuated'],
  ];
  for (const [id, caption] of picks) {
    const found = data.states.find((s) => s.id === id);
    if (!found) continue;
    const row = el('div', `state-row ${found.className} enter-row`);
    const glyph = el('span', `glyph tone-${found.tone}`);
    glyph.innerHTML = found.glyph;
    row.append(glyph, el('span', 'state-label', caption), el('span', 't-meta', found.label));
    children.append(row);
  }
}

function renderMotions() {
  const host = $('#motions');
  host.replaceChildren();
  for (const moment of data.transitions) {
    const row = el('div', 'motion-row');
    row.append(
      el('span', '', `${moment.moment} · ${moment.property}`),
      el('span', 'motion-state', `${moment.ms}ms · reduced: ${moment.reducedMotion}`),
    );
    host.append(row);
  }
}

function renderThinking() {
  const host = $('#thinking');
  host.replaceChildren();
  [...'Thinking'].forEach((character, index) => {
    const span = el('span', '', character);
    span.style.setProperty('--i', String(index));
    host.append(span);
  });
}

function renderChips() {
  const host = $('#chips');
  host.replaceChildren();
  const sources = ['docs.opencode.dev', 'github.com', 'arxiv.org', 'news.ycombinator.com', 'qoder.com'];
  sources.forEach((domain, index) => {
    const chip = el('span', 'source-chip', domain.slice(0, 2).toUpperCase());
    chip.style.setProperty('--i', String(index));
    chip.title = domain;
    host.append(chip);
  });
}

function renderSkeletons() {
  const host = document.querySelectorAll('.skeleton');
  host.forEach((node) => {
    node.style.animation = 'none';
    void node.offsetWidth;
    node.style.animation = '';
  });
}

function resetDemos() {
  const commit = $('#commit');
  commit.dataset.phase = 'rehearsing';
  commit.querySelector('.commit-label').textContent = 'rehearsing';
  $('#commit-next').textContent = 'Commit';
  $('#approval-slot').replaceChildren();
  $('#approval-toggle').textContent = 'Raise approval bar';
  const receipt = $('#receipt');
  receipt.removeAttribute('data-recovery');
  void receipt.offsetWidth;
  receipt.dataset.recovery = 'rolled-back';
  renderChips();
  renderSkeletons();
  renderThinking();
}

function wireDemos() {
  $('#contrast').addEventListener('change', (event) => {
    state.contrast = event.target.checked;
    apply();
  });

  $('#commit-next').addEventListener('click', () => {
    const commit = $('#commit');
    const label = commit.querySelector('.commit-label');
    const button = $('#commit-next');
    if (commit.dataset.phase === 'rehearsing') {
      commit.dataset.phase = 'committing';
      label.textContent = 'committing';
      button.textContent = 'Reset';
      window.setTimeout(() => {
        commit.dataset.phase = 'committed';
        label.textContent = 'committed';
      }, 200);
    } else {
      commit.dataset.phase = 'rehearsing';
      label.textContent = 'rehearsing';
      button.textContent = 'Commit';
    }
  });

  $('#approval-toggle').addEventListener('click', () => {
    const slot = $('#approval-slot');
    const button = $('#approval-toggle');
    if (slot.childElementCount > 0) {
      slot.replaceChildren();
      button.textContent = 'Raise approval bar';
      return;
    }
    const bar = el('div', 'approval-bar');
    bar.style.marginTop = 'var(--sp-3)';
    bar.append(
      el('div', 't-section', 'Needs approval: write 3 files in apps/desktop'),
      el(
        'div',
        't-meta',
        'effect: file.write · target: apps/desktop/src · data: internal · risk: R1 reversible · duration: 2s',
      ),
    );
    const actions = el('div', 'demo-row');
    actions.style.marginTop = 'var(--sp-2)';
    const approve = el('button', 'btn btn-primary', 'Approve with signature');
    const deny = el('button', 'btn btn-quiet', 'Deny');
    approve.type = 'button';
    deny.type = 'button';
    actions.append(approve, deny);
    bar.append(actions);
    slot.append(bar);
    button.textContent = 'Hide approval bar';
  });

  $('#rollback').addEventListener('click', () => {
    const receipt = $('#receipt');
    receipt.removeAttribute('data-recovery');
    void receipt.offsetWidth;
    receipt.dataset.recovery = 'rolled-back';
  });

  $('#chips-reset').addEventListener('click', renderChips);
  $('#skeleton-reset').addEventListener('click', renderSkeletons);
  $('#reset-demos').addEventListener('click', resetDemos);

  document.addEventListener('visibilitychange', () => {
    document.documentElement.classList.toggle('is-window-hidden', document.hidden);
  });
}

function startTimer() {
  const target = $('#spec-timer');
  const started = Date.now();
  const pad = (n) => String(n).padStart(2, '0');
  window.setInterval(() => {
    if (document.hidden) return;
    const seconds = Math.floor((Date.now() - started) / 1000);
    target.textContent = `${pad(Math.floor(seconds / 3600))}:${pad(Math.floor(seconds / 60) % 60)}:${pad(seconds % 60)}`;
  }, 1000);
}

function render() {
  renderThemes();
  renderModes();
  renderSerifs();
  renderSwatches();
  renderFloors();
  renderTokens();
  renderStates();
  renderMotions();
  $('#status').textContent = `${data.variants.length} variants · ${data.states.length} states`;
}

store.read();
$('#contrast').checked = state.contrast;
wireDemos();
renderThinking();
renderChips();
renderFonts();
apply();
startTimer();
